public static String applyRelativePath(String path, String relativePath) {
    // Split the path and relative path into their individual components
    String[] pathComponents = path.split("/");
    String[] relativePathComponents = relativePath.split("/");

    // Check if the relative path is absolute (i.e. starts with a '/')
    boolean isAbsolute = relativePathComponents[0].equals("");

    // Rebuild the path using the relative path components
    StringBuilder rebuiltPath = new StringBuilder();
    for (int i = isAbsolute ? 1 : 0; i < relativePathComponents.length; i++) {
        rebuiltPath.append(relativePathComponents[i]);
        if (i < relativePathComponents.length - 1) {
            rebuiltPath.append("/");
        }
    }

    // Append the path components to the rebuilt path
    for (int i = isAbsolute ? 0 : 1; i < pathComponents.length; i++) {
        rebuiltPath.append("/");
        rebuiltPath.append(pathComponents[i]);
    }

    return rebuiltPath.toString();
}

